/**
 * A matemática noturna das plantas — porte de `componentes/viz/planta_noite.js`.
 *
 * De dia a planta guarda amido; de noite, sem luz, ela vive dele. O que a
 * pesquisa achou é que ela não gasta de qualquer jeito: ela DIVIDE a reserva
 * pelas horas que faltam até o amanhecer e queima exatamente nesse ritmo. Rápido
 * demais e ela passa fome antes do sol; devagar demais e sobra amido que poderia
 * ter virado crescimento.
 *
 * Por isso a cena é um gráfico, e não uma planta: o que se quer ver é a reta da
 * reserva encostando no zero bem na linha do amanhecer.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

function virgula(n: number): string {
  return n.toFixed(1).replace('.', ',');
}

const plantaNoite: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const ritmo = Math.max(0.1, numeroDe(valores, 'r', 0));
    const amido = numeroDe(info, 'amido', 100);
    const horas = numeroDe(info, 'horas', 10);
    const ok = info.ok === true;
    const acaba = amido / ritmo;

    titulo(ctx, L, A, 'A reserva tem de durar até o sol nascer');

    const mx = L * 0.12;
    const my = A * 0.2;
    const gw = L * 0.76;
    const gh = A * 0.48;

    // A noite corre da esquerda para a direita, e a alvorada acende no fim.
    const ceu = ctx.createLinearGradient(mx, 0, mx + gw, 0);
    ceu.addColorStop(0, cor.palha);
    ceu.addColorStop(0.8, cor.palha);
    ceu.addColorStop(1, 'rgb(240 170 70 / 35%)');
    ctx.fillStyle = ceu;
    ctx.fillRect(mx, my, gw, gh);

    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1;
    ctx.strokeRect(mx, my, gw, gh);

    // Lua no anoitecer, sol no amanhecer — as duas pontas da conta.
    ctx.fillStyle = cor.fraco;
    ctx.beginPath();
    ctx.arc(mx + 16, my + 16, 7, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = cor.ouro;
    ctx.beginPath();
    ctx.arc(mx + gw - 14, my + 16, 8, 0, Math.PI * 2);
    ctx.fill();

    const xAmanhecer = mx + gw;
    ctx.strokeStyle = cor.ouro;
    ctx.setLineDash([4, 3]);
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(xAmanhecer, my);
    ctx.lineTo(xAmanhecer, my + gh);
    ctx.stroke();
    ctx.setLineDash([]);

    // A reta da reserva: cheia no anoitecer, caindo no ritmo escolhido.
    const xPorHora = gw / horas;
    const xZero = mx + Math.min(acaba, horas) * xPorHora;
    const yZero = my + Math.min(acaba / horas, 1) * gh;

    ctx.strokeStyle = ok ? cor.verde : cor.erro;
    ctx.lineWidth = 2.8;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(mx, my);
    ctx.lineTo(xZero, yZero);
    ctx.stroke();

    // Se zerou antes do amanhecer, o resto da noite é jejum.
    if (acaba < horas) {
      ctx.strokeStyle = cor.erro;
      ctx.lineWidth = 2.8;
      ctx.beginPath();
      ctx.moveTo(xZero, my + gh);
      ctx.lineTo(xAmanhecer, my + gh);
      ctx.stroke();

      texto(ctx, 'fome', (xZero + xAmanhecer) / 2, my + gh - 9, limitar(A * 0.036, 9, 12), {
        cor: cor.erro,
        peso: 700,
      });
    }

    const miudo = limitar(A * 0.034, 8, 11);
    texto(ctx, 'amido', mx, my - 8, miudo, { cor: cor.fraco, alinhamento: 'left' });
    texto(ctx, 'anoitecer', mx, my + gh + 12, miudo, { cor: cor.fraco, alinhamento: 'left' });
    texto(ctx, 'amanhecer', xAmanhecer, my + gh + 12, miudo, {
      cor: cor.fraco,
      alinhamento: 'right',
    });

    // A conta em pessoa — é ela o assunto do módulo.
    texto(
      ctx,
      `${amido} de amido ÷ ${horas} h = ${virgula(amido / horas)}/h  ·  seu ritmo: ${virgula(ritmo)}/h`,
      L / 2,
      my + gh + 30,
      limitar(A * 0.042, 9, 13),
      { cor: ok ? cor.verde : cor.texto, peso: 700 },
    );

    rodape(
      ctx,
      L,
      A,
      ok,
      'O amido dura exatamente até o amanhecer ✔',
      acaba < horas
        ? 'Acabou cedo: a planta passa fome antes do sol.'
        : 'Sobra amido ao amanhecer: crescimento desperdiçado.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A }) => desenhar(ctx, L, A),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default plantaNoite;
